import React from "react";
import "./ProductList.scss"; // Reutiliza o mesmo arquivo de estilo

const Product = ({ product }) => {
  // Verifica se o produto e suas propriedades existem
  if (!product || !product.items || !product.items[0] || !product.items[0].sellers || !product.items[0].sellers[0]) {
    return <div className="product">Dados do produto incompletos.</div>;
  }

  const offer = product.items[0].sellers[0].commertialOffer;
  const price = offer ? offer.Price / 100 : 0; // Converte o preço para reais

  return (
    <div className="product">
      <h3>{product.productName}</h3>
      <p>Marca: {product.brand}</p>
      <p>Preço: R$ {price.toFixed(2)}</p>
    </div>
  );
};

export default Product;
